window.MealComposer=(()=>{
const ingredient=(name,grams,calories,protein,carbs)=>({name,grams,calories,protein,carbs});
const noodle=()=>ingredient('Cooked wheat noodles',250,138,4.5,25),rice=()=>ingredient('Cooked white rice',250,130,2.7,28.2),pork=()=>ingredient('Cooked minced pork',80,260,25,0),chicken=()=>ingredient('Cooked chicken',100,165,31,0),veg=()=>ingredient('Vegetables',80,25,1.2,4.5),oil=()=>ingredient('Cooking oil',8,884,0,0),sauce=()=>ingredient('Bean sauce',35,160,5,25),egg=()=>ingredient('Egg',50,155,12.6,1.1),tofu=()=>ingredient('Tofu',120,144,17,2.8);
const dishes=[
{name:'Zhajiang mian · 炸酱面',aliases:'zha jiang mian zhajiangmian fried sauce noodles 炸酱面',parts:[noodle(),pork(),sauce(),veg(),oil()]},
{name:'Chicken rice',aliases:'hainanese chicken rice 鸡饭',parts:[rice(),chicken(),veg(),oil(),ingredient('Sauce',25,100,2,20)]},
{name:'Fried rice',aliases:'egg fried rice 炒饭',parts:[rice(),egg(),veg(),oil()]},
{name:'Chicken noodle bowl',aliases:'chicken noodles 鸡肉面',parts:[noodle(),chicken(),veg(),oil(),sauce()]},
{name:'Tofu rice bowl',aliases:'vegetarian tofu rice 豆腐饭',parts:[rice(),tofu(),veg(),oil(),sauce()]},
{name:'Minced pork rice',aliases:'pork rice bowl 肉燥饭',parts:[rice(),pork(),veg(),sauce(),oil()]},
{name:'Noodle bowl template',aliases:'noodles mian mee 面',parts:[noodle(),pork(),veg(),sauce(),oil()],template:true},
{name:'Rice bowl template',aliases:'rice bowl 饭',parts:[rice(),chicken(),veg(),oil()],template:true},
{name:'Salad bowl template',aliases:'salad',parts:[ingredient('Vegetables',200,25,1.2,4.5),chicken(),ingredient('Dressing / oil',15,884,0,0)],template:true}
];
let current=null,chosen=null;const form=document.querySelector('#mealForm'),name=form.elements.name;
const host=document.createElement('div');host.className='dish-composer';name.closest('label').after(host);
host.innerHTML='<p class="dish-help">Type the dish you ate, including mixed meals. Choose an estimate or enter your own nutrition below.</p><div class="dish-results" aria-live="polite"></div><div class="dish-editor" hidden></div>';
const results=host.querySelector('.dish-results'),editor=host.querySelector('.dish-editor');
const norm=s=>s.toLowerCase().replace(/[\s·_-]+/g,'');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function recent(){try{return [...new Map(JSON.parse(localStorage.getItem('form-fuel-v1')||'{}').meals?.slice().reverse().map(m=>[m.name,m])||[]).values()].slice(0,12);}catch{return [];}}
function search(){current=null;chosen=null;editor.hidden=true;const q=norm(name.value);const saved=recent().filter(m=>q&&norm(m.name).includes(q)).slice(0,3);const matches=dishes.filter(d=>!d.template&&(!q||norm(d.name+' '+d.aliases).includes(q))).slice(0,4);results.innerHTML=(saved.length?'<p class="dish-kicker">YOUR RECENT MEALS</p>':'')+saved.map((m,i)=>'<button type="button" data-recent="'+i+'">↺ '+esc(m.name)+' <small>Use previous values</small></button>').join('')+(matches.length?'<p class="dish-kicker">WHOLE-DISH ESTIMATES</p>':'<p>No exact preset yet. Keep your dish name and start from a similar bowl, or enter nutrition from a menu or label.</p>')+matches.map(d=>'<button type="button" data-dish="'+dishes.indexOf(d)+'">'+esc(d.name)+' <span>↗</span></button>').join('')+'<div class="dish-templates">'+dishes.filter(d=>d.template).map(d=>'<button type="button" data-dish="'+dishes.indexOf(d)+'">'+esc(d.name.replace(' template',''))+' +</button>').join('')+'</div>';
results.querySelectorAll('[data-dish]').forEach(b=>b.onclick=()=>select(dishes[Number(b.dataset.dish)]));results.querySelectorAll('[data-recent]').forEach(b=>b.onclick=()=>{const m=saved[Number(b.dataset.recent)];name.value=m.name;for(const k of ['calories','protein','carbs'])form.elements[k].value=m[k];current={type:'previous meal',name:m.name};results.innerHTML='<p class="dish-confirm">Previous meal values loaded. Adjust them below for today’s portion.</p>';});}
function totals(parts,multiplier){return parts.reduce((a,p)=>{for(const k of ['calories','protein','carbs'])a[k]+=p[k]*p.grams/100*multiplier;return a;},{calories:0,protein:0,carbs:0});}
function select(d){chosen=structuredClone(d);if(!d.template||!name.value.trim())name.value=d.name.replace(' template','');current=null;editor.hidden=false;editor.innerHTML='<div class="dish-editor-heading"><strong>'+esc(d.name)+'</strong><span>Recipe estimate</span></div><label>How much did you eat?<select id="dishServings"><option value="0.5">½ portion</option><option value="0.75">¾ portion</option><option value="1" selected>1 regular portion</option><option value="1.5">1½ portions</option><option value="2">2 portions</option></select></label><details><summary>Adjust what’s in your bowl</summary><p>Weights below are for one regular portion, after cooking. Replace nutrition values below if your ingredients differ.</p>'+chosen.parts.map((p,i)=>'<label class="dish-part">'+esc(p.name)+'<span><input type="number" min="0" max="2000" step="1" data-component="'+i+'" value="'+p.grams+'" aria-label="'+esc(p.name)+' grams"> g</span></label>').join('')+'</details><div class="dish-total" role="status"></div><p class="dish-uncertainty">Approximate recipe, not restaurant nutrition. Meat fat, sauces, oil and bowl size can change the result substantially.</p><button type="button" class="primary full" id="applyDish">Use this estimate ↗</button>';
function preview(){const multiplier=Number(editor.querySelector('#dishServings').value);const t=totals(chosen.parts,multiplier);editor.querySelector('.dish-total').textContent=Math.round(t.calories)+' kcal · '+t.protein.toFixed(1)+' g protein · '+t.carbs.toFixed(1)+' g carbs';return {t,multiplier};}
editor.oninput=e=>{current=null;if(e.target.dataset.component!==undefined){chosen.parts[Number(e.target.dataset.component)].grams=Math.max(0,Math.min(2000,Number(e.target.value)||0));}preview();};editor.onchange=()=>{current=null;preview();};
editor.querySelector('#applyDish').onclick=()=>{const {t,multiplier}=preview();ingredients=[];document.querySelector('#ingredients').innerHTML='';for(const k of ['calories','protein','carbs'])form.elements[k].value=k==='calories'?Math.round(t[k]):t[k].toFixed(1);current={type:'dish recipe estimate',preset:chosen.name,portions:multiplier,parts:structuredClone(chosen.parts)};results.innerHTML='<p class="dish-confirm">✓ Estimate added. Review the editable nutrition values below, then save your meal.</p>';editor.querySelector('#applyDish').textContent='Estimate applied ✓';};preview();}
name.addEventListener('input',search);document.addEventListener('meal:opened',()=>{current=null;chosen=null;search();});search();return {clearEstimate(){current=null;editor.hidden=true;},get current(){return current;},totals,dishes};
})();
